# frozen_string_literal: true

# User-related shared contexts for different user types and verification states
RSpec.shared_context "user contexts" do
  # Basic user types
  let(:owner_user) { create(:user, :owner, :verified, email: 'owner@test.com', password: 'password123') }
  let(:coach_user) { create(:user, :coach, :verified, email: 'coach@test.com', password: 'password123') }
  let(:member_user) { create(:user, :member, :verified, email: 'member@test.com', password: 'password123') }

  # Unverified states
  let(:unverified_owner) { create(:user, :owner, :unverified, email: 'unverified_owner@test.com', password: 'password123') }
  let(:unverified_coach) { create(:user, :coach, :unverified, email: 'unverified_coach@test.com', password: 'password123') }
  let(:unverified_member) { create(:user, :member, :unverified, email: 'unverified_member@test.com', password: 'password123') }

  # Unconfirmed states
  let(:unconfirmed_owner) { create(:user, :owner, :unconfirmed, email: 'unconfirmed@test.com', password: 'password123') }
  let(:unconfirmed_coach) { create(:user, :coach, :unconfirmed, email: 'unconfirmed_coach@test.com', password: 'password123') }
  let(:unconfirmed_member) { create(:user, :member, :unconfirmed, email: 'unconfirmed_member@test.com', password: 'password123') }

  # Different providers
  let(:google_owner) { create(:user, :owner, :google_user, :verified, email: 'google_owner@test.com') }
  let(:google_member) { create(:user, :member, :google_user, :verified, email: 'google_member@test.com') }
  let(:phone_member) { create(:user, :member, :phone_user, phone_number: '+6281234567890') }

  # Multiple users for testing interactions
  let(:other_owner) { create(:user, :owner, :verified, email: 'other_owner@test.com', password: 'password123') }
  let(:additional_member) { create(:user, :member, :verified, email: 'additional_member@test.com', password: 'password123') }

  # Users with specific attributes for testing
  let(:user_with_profile) do
    user = create(:user, :member, :verified, email: 'profile_user@test.com', password: 'password123')
    create(:user_profile, user: user, bio: 'Test bio', date_of_birth: 25.years.ago)
    user
  end
end

# Specific user role contexts
RSpec.shared_context "owner users" do
  include_context "user contexts"

  let(:current_user) { owner_user }
  let(:verified_user) { owner_user }
  let(:unverified_user) { unverified_owner }
  let(:unconfirmed_user) { unconfirmed_owner }
end

RSpec.shared_context "coach users" do
  include_context "user contexts"

  let(:current_user) { coach_user }
  let(:verified_user) { coach_user }
  let(:unverified_user) { unverified_coach }
  let(:unconfirmed_user) { unconfirmed_coach }
end

RSpec.shared_context "member users" do
  include_context "user contexts"

  let(:current_user) { member_user }
  let(:verified_user) { member_user }
  let(:unverified_user) { unverified_member }
  let(:unconfirmed_user) { unconfirmed_member }
end

# User verification state contexts
RSpec.shared_context "verified users" do
  let(:verified_owner) { create(:user, :owner, :verified, email: 'verified_owner@test.com', password: 'password123') }
  let(:verified_coach) { create(:user, :coach, :verified, email: 'verified_coach@test.com', password: 'password123') }
  let(:verified_member) { create(:user, :member, :verified, email: 'verified_member@test.com', password: 'password123') }
end

RSpec.shared_context "unverified users" do
  let(:unverified_owner) { create(:user, :owner, :unverified, email: 'unverified_owner@test.com', password: 'password123') }
  let(:unverified_coach) { create(:user, :coach, :unverified, email: 'unverified_coach@test.com', password: 'password123') }
  let(:unverified_member) { create(:user, :member, :unverified, email: 'unverified_member@test.com', password: 'password123') }
end

RSpec.shared_context "unconfirmed users" do
  let(:unconfirmed_owner) { create(:user, :owner, :unconfirmed, email: 'unconfirmed_owner@test.com', password: 'password123') }
  let(:unconfirmed_coach) { create(:user, :coach, :unconfirmed, email: 'unconfirmed_coach@test.com', password: 'password123') }
  let(:unconfirmed_member) { create(:user, :member, :unconfirmed, email: 'unconfirmed_member@test.com', password: 'password123') }
end

# User attribute contexts for testing specific scenarios
RSpec.shared_context "users with valid attributes" do
  let(:valid_user_attributes) do
